11	use tempfile::TempDir;
12	
13	use crate::deref_field;
14	
15	use super::args::{File, FileArg, Write};
16	use super::parse::ParsedFile;
17	use terminators::OutputTerminator;
18	
19	impl ParsedFile<'_, '_> {
20	    pub fn execute(&self) -> io::Result<()> {
21	        let mut state = FileExecutor::initialize(self)?;
22	        let out: File<Write> = (&self.source.arg).into();
23	        state.execute(&out)
24	    }
25	}
26	
27	pub struct FileExecutor<'a> {
28	    pub file: &'_ ParsedFile<'a>,
29	    cmd: process::Command,
30	    output_terminators: Vec<OutputTerminator>,
31	    temp_dir: TempDir,
32	}
33	
34	deref_field! { impl<'a> *FileExecutor<'a> = .file: ParsedFile<'a> }
35	
36	impl<'strs> FileExecutor<'strs> {
37	    pub fn initialize(file: &'strs ParsedFile<'strs>) -> io::Result<FileExecutor<'strs>> {
38	        let source = file.source.to_string();
39	        let source_ext = source.rsplit_terminator('.').next().unwrap_or("");
40	        let temp_dir = tempfile::Builder::new().prefix("cogshell-").tempdir()?;
41	        let temp_path = temp_dir.path();
42	
43	        let mut env = vec![];
44	
45	        macro_rules! var {
46	            ($namefmt:literal => $val:expr) => {
47	                env.push((format!("COGSH_{}", $namefmt), $val));
48	            };
49	            ($namefmt:literal [$i:expr] => $val:expr) => {
50	                env.push((format!("COGSH_{}_{}", $namefmt, $i), $val));
51	            };
52	        }
53	        macro_rules! path {
54	            ($fname:expr, $content:expr) => {{
55	                let path = temp_path.join($fname);
56	                fs::write(&path, $content)?;
57	                path.to_str().unwrap().to_owned()
58	            }};
59	        }
60	
61	        // nonces to figure out where output from one block ends and the next begins
62	        let output_terminators: Vec<_> = iter::repeat_with(OutputTerminator::new)
63	            .take(file.blocks.len() + 1)
64	            .collect();
65	
66	        var!("TEMP_DIR" => temp_path.to_str().unwrap().to_owned());
67	        var!("SOURCE" => source.clone());
68	        var!("NUM_BLOCKS" => file.blocks.len().to_string());
69	        var!("PROLOGUE" => path!("prologue.sh", file.args.prologue.join("\n")));
