use std::sync::LazyLock;

use base64_encode::base64_encode;
use regex::Regex;

#[derive(Copy, Clone, Debug)]
pub enum ChecksumKind {
    Md5Hex,
    Md5Base64Prefix10Chars,
}

impl ChecksumKind {
    fn label(&self) -> &'static str {
        match self {
            Self::Md5Hex => "checksum",
            Self::Md5Base64Prefix10Chars => "sum",
        }
    }

    fn from_label(label: &str) -> Option<ChecksumKind> {
        match label {
            l if l == Self::Md5Hex.label() => Some(Self::Md5Hex),
            l if l == Self::Md5Base64Prefix10Chars.label() => Some(Self::Md5Base64Prefix10Chars),
            _ => None,
        }
    }
}

static CHECKSUM_RE: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(
        r"(?x-u)
          \A # must start immediately
          \x20*  # (spaces)
          \(
            (?<kind> checksum | sum )
            :
            (?<hash> [a-zA-Z0-9+/-_]+ )
          \)
        ",
    )
    .unwrap()
});

#[derive(Debug)]
pub struct Checksum<'strs> {
    kind: ChecksumKind,
    hash: &'strs str,
}

impl<'strs> Checksum<'strs> {
    /// Search for an output hash suffix following a CogShell block, given the str starting immediately after output end mark
    pub fn from_block_suffix(block_sfx: &'strs str) -> Option<Checksum<'strs>> {
        let caps = CHECKSUM_RE.captures(block_sfx)?;
        let kind = ChecksumKind::from_label(caps.name("kind")?.as_str())?;
        let hash = caps.name("hash")?.as_str();
        Some(Self { kind, hash })
    }

    /// Validate this saved output hash against the output
    pub fn matches(&self, output: &str) -> bool {
        let hash_computed = md5::compute(output);
        let hash_comp_str = match self.kind {
            ChecksumKind::Md5Hex => format!("{:x}", hash_computed),
            ChecksumKind::Md5Base64Prefix10Chars => {
                base64_encode(&hash_computed.0)[..10].to_string()
            }
        };
        self.hash == &hash_comp_str
    }
}

#!/usr/bin/env bash
set -euo pipefail

if test -f "${COGSH_PROLOGUE:-}"; then
  echo "executing prologue for $COGSH_SOURCE..." >&2
  source "$COGSH_PROLOGUE" --
fi
printf "\n%s\n" "$1"; shift  # prologue terminator

for ((i=1; i<=$COGSH_NUM_BLOCKS; i++)); do
  export COGSH_BLOCK_PROG=${!COGSH_BLOCK_PROG_$i}
  export COGSH_BLOCK_LINE=${!COGSH_BLOCK_LINE_$i}
  export COGSH_BLOCK_COL=${!COGSH_BLOCK_COL_$i}
  export COGSH_BLOCK_OFFSET=${!COGSH_BLOCK_OFFSET_$i}
  export COGSH_BLOCK_OUTPUT_PFX=${!COGSH_BLOCK_OUTPUT_PFX_$i}
  export COGSH_BLOCK_OUTPUT_PREV=${!COGSH_BLOCK_OUTPUT_PREV_$i}

  echo "executing block at $COGSH_SOURCE:$COGSH_BLOCK_LINE:$COGSH_BLOCK_COL..." >&2

  source "$COGSH_BLOCK_PROG" --
  printf "\n%s\n" "$1"; shift  # block terminator
done

