impl File<Read> {
    /// Reads the full contents of the file into memory.
    pub fn read(&mut self) -> io::Result<String> {
        let mut content = String::new();
        match &self.arg {
            FileArg::Stream => {
                io::stdin().lock().read_to_string(&mut content)?;
            }
            FileArg::OnDisk(path) => {
                fs::File::open(path)?.read_to_string(&mut content)?;
            }
        }
        Ok(content)
    }
}

impl File<Write> {
    /// Open this file (or stdout) for writing, applying `line_suffix` to each output line.
    pub fn open(&self, line_suffix: String) -> io::Result<Box<dyn io::Write>> {
        let inner: Box<dyn io::Write> = match &self.arg {
            FileArg::Stream => Box::new(io::stdout()),
            FileArg::OnDisk(path) => Box::new(AtomicFileWriter::new(path.clone())?),
        };
        if line_suffix.is_empty() {
            Ok(inner)
        } else {
            let transform = move |line: &mut String| {
                if let Some(stripped) = line.strip_suffix('\n') {
                    let mut new_line = String::with_capacity(stripped.len() + line_suffix.len() + 1);
                    new_line.push_str(stripped);
                    new_line.push_str(&line_suffix);
                    new_line.push('\n');
                    *line = new_line;
                } else {
                    line.push_str(&line_suffix);
                }
            };
            Ok(Box::new(LineTransformWriter::new(inner, transform)))
        }
    }
}

